1	(function () {
2	  'use strict';
3	
4	  var NO_REPLY = 'Could not reach the server.';
5	  var FALLBACK = 'Request failed.';
6	
7	  var form = document.getElementById('booking-form');
8	  var roomSelect = document.getElementById('room');
9	  var titleInput = document.getElementById('title');
10	  var dateInput = document.getElementById('date');
11	  var startInput = document.getElementById('start');
12	  var endInput = document.getElementById('end');
13	  var bookButton = document.getElementById('book');
14	  var filterInput = document.getElementById('filter-date');
15	  var showAllButton = document.getElementById('show-all');
16	  var list = document.getElementById('booking-list');
17	  var errorBox = document.getElementById('error');
18	
19	  var listSequence = 0;
20	
21	  // Resolves to { reached: false } when there is no usable reply, otherwise
22	  // { reached: true, status, body }. A 204 body is never read; any other body
23	  // that cannot be read or parsed as JSON counts as no reply.
24	  async function request(url, options) {
25	    var reply;
26	    try {
27	      reply = await fetch(url, options);
28	    } catch {
29	      return { reached: false };
30	    }
31	    if (reply.status === 204) {
32	      return { reached: true, status: 204, body: null };
33	    }
34	    try {
35	      return { reached: true, status: reply.status, body: await reply.json() };
36	    } catch {
37	      return { reached: false };
38	    }
39	  }
40	
41	  function isPlainObject(value) {
42	    return value !== null && typeof value === 'object' && !Array.isArray(value);
43	  }
44	
45	  // The array under `key` of a 200 reply, or null when the reply is not one.
46	  function arrayFrom(outcome, key) {
47	    var ok = outcome.reached && outcome.status === 200 &&
48	      isPlainObject(outcome.body) && Array.isArray(outcome.body[key]);
49	    return ok ? outcome.body[key] : null;
50	  }
51	
52	  function errorMessage(body) {
53	    return isPlainObject(body) && typeof body.error === 'string' ? body.error : FALLBACK;
54	  }
55	
56	  function showError(text) {
57	    errorBox.textContent = text;
58	  }
59	
60	  function showOutcomeError(outcome) {
61	    showError(outcome.reached ? errorMessage(outcome.body) : NO_REPLY);
62	  }
63	
64	  function listUrl() {
65	    var date = filterInput.value;
66	    return date === '' ? '/api/bookings' : '/api/bookings?date=' + date;
67	  }
68	
69	  function bookingText(booking) {
70	    return booking.date + ' ' + booking.start + '-' + booking.end + ' ' +
71	      booking.room + ': ' + booking.title;
72	  }
73	
74	  function bookingItem(booking) {
75	    var item = document.createElement('li');
76	    var cancel = document.createElement('button');
77	    cancel.type = 'button';
78	    cancel.textContent = 'Cancel';
79	    cancel.addEventListener('click', function () {
80	      cancelBooking(booking.id, cancel);
81	    });
82	    item.append(bookingText(booking), cancel);
83	    return item;
84	  }
85	
86	  function renderList(bookings) {
87	    if (bookings.length === 0) {
88	      var empty = document.createElement('li');
89	      empty.append('No bookings.');
90	      list.replaceChildren(empty);
91	      return;
92	    }
93	    list.replaceChildren(...bookings.map(bookingItem));
94	  }
95	
96	  async function loadList() {
97	    listSequence += 1;
98	    var mine = listSequence;
99	    var outcome = await request(listUrl());
100	    if (mine !== listSequence) {
101	      return;
102	    }
103	    var bookings = arrayFrom(outcome, 'bookings');
104	    if (bookings) {
105	      renderList(bookings);
106	      return;
107	    }
108	    showOutcomeError(outcome);
109	  }
110	
111	  function roomOption(name) {
112	    var option = document.createElement('option');
113	    option.value = name;
114	    option.textContent = name;
115	    return option;
116	  }
117	
118	  async function loadRooms() {
119	    var outcome = await request('/api/rooms');
120	    var rooms = arrayFrom(outcome, 'rooms');
121	    if (rooms) {
122	      roomSelect.replaceChildren(...rooms.map(roomOption));
123	      return;
124	    }
125	    showOutcomeError(outcome);
126	  }
127	
128	  function bookingPayload() {
129	    return JSON.stringify({
130	      room: roomSelect.value,
131	      title: titleInput.value,
132	      date: dateInput.value,
133	      start: startInput.value,
134	      end: endInput.value
135	    });
136	  }
137	
138	  async function submitBooking(event) {
139	    event.preventDefault();
140	    if (bookButton.disabled) {
141	      return;
142	    }
143	    bookButton.disabled = true;
144	    var outcome = await request('/api/bookings', {
145	      method: 'POST',
146	      headers: { 'Content-Type': 'application/json' },
147	      body: bookingPayload()
148	    });
149	    bookButton.disabled = false;
150	    if (outcome.reached && outcome.status === 201) {
151	      titleInput.value = '';
152	      showError('');
153	      loadList();
154	      return;
155	    }
156	    showOutcomeError(outcome);
157	  }
158	
159	  async function cancelBooking(id, button) {
160	    button.disabled = true;
161	    var outcome = await request('/api/bookings/' + id, { method: 'DELETE' });
162	    button.disabled = false;
163	    if (!outcome.reached) {
164	      showError(NO_REPLY);
165	      return;
166	    }
167	    showError(outcome.status === 204 ? '' : errorMessage(outcome.body));
168	    loadList();
169	  }
170	
171	  function showAll() {
172	    filterInput.value = '';
173	    loadList();
174	  }
175	
176	  form.addEventListener('submit', submitBooking);
177	  filterInput.addEventListener('change', loadList);
178	  showAllButton.addEventListener('click', showAll);
179	
180	  loadRooms();
181	  loadList();
182	}());
