1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Room bookings</title>
7	<style>
8	  :root { color-scheme: light dark; --accent: #2f6fdf; --muted: #6b7280; --danger: #c0392b; }
9	  * { box-sizing: border-box; }
10	  body { font: 16px/1.5 system-ui, sans-serif; max-width: 42rem; margin: 2rem auto; padding: 0 1rem; }
11	  h1 { font-size: 1.75rem; margin: 0 0 1.5rem; }
12	  h2 { font-size: 1.15rem; margin: 2rem 0 0.75rem; }
13	  form { display: grid; grid-template-columns: max-content 1fr; gap: 0.6rem 1rem; align-items: center; }
14	  label { font-weight: 600; }
15	  input, select, button { font: inherit; padding: 0.4rem 0.6rem; border: 1px solid var(--muted); border-radius: 6px; }
16	  button { cursor: pointer; background: var(--accent); color: #fff; border-color: var(--accent); }
